{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required = set(case['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
        else:
            children[n['parent']].append(n['id'])
    retained = set(node_map.keys())
    sorted_nodes = sorted(node_map.keys(), key=lambda nid: (-node_map[nid]['depth'], nid))
    removed = []
    for nid in sorted_nodes:
        if nid not in retained:
            continue
        node = node_map[nid]
        if nid == root_id:
            continue
        if node['symbol'] in required:
            continue
        if not node['removable']:
            continue
        has_retained_child = any(cid in retained for cid in children[nid])
        if has_retained_child:
            continue
        retained.remove(nid)
        removed.append(nid)
    retained_sorted = sorted(retained)
    return {'removed_node_ids': removed, 'retained_node_ids': retained_sorted}"
}
